mapper.sql:
WHERE STATUS = 'active'

  AND EMPLOYEE_NAME LIKE CONCAT('%', #{criteria.keyword}, '%')


  AND DEPARTMENT_ID = #{criteria.departmentId}


  AND JOB_ID = #{criteria.jobId}


  AND SALARY >= #{criteria.salaryFrom}


  AND SALARY <= #{criteria.salaryTo}

mapper.update:
UPDATE EMPLOYEE
   SET EMPLOYEE_NAME = #{employeeName}, DEPARTMENT_ID = #{departmentId},
       JOB_ID = #{jobId}, SALARY = #{salary}, ENTRANCE_DATE = #{entranceDate},
       VERSION = #{version}
 WHERE EMPLOYEE_ID = #{employeeId}
